import fs from 'node:fs';
import {fileURLToPath} from 'node:url';
import {m100 as m} from '../curriculum/m100.js';
import {block3} from '../curriculum/m100-block3.js';
import {audit} from '../curriculum/m100-audit.js';
import {rubric} from '../curriculum/m100-rubric.js';
import {block2} from '../curriculum/m100-block2.js';
import {block1} from '../curriculum/m100-block1.js';
import {computing} from '../curriculum/m100-computing.js';
import {a101Blocks} from '../curriculum/a101-blocks.js';
import {a101,a101Sources} from '../curriculum/a101.js';
import {m101Blocks} from '../curriculum/m101-blocks.js';
import {m102Units} from '../curriculum/m102-units.js';
import {m102Blocks} from '../curriculum/m102-blocks.js';
import {p101Units} from '../curriculum/p101-units.js';
import {p101Blocks} from '../curriculum/p101-blocks.js';
import {m101Units} from '../curriculum/m101-units.js';
import {stage1Map as stageMap} from '../curriculum/stage1-map.js';
import {constructionPolicy as policy} from '../curriculum/construction-policy.js';
import {blueprint} from '../curriculum/blueprint.js';
import {bridge,stage1Modules,semesters} from '../curriculum/stage1.js';
import {coverage,gaps,sources} from '../curriculum/coverage.js';
const root = fileURLToPath(new URL('../', import.meta.url));
const e = value => String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const unitHours=m.units.reduce((sum,u)=>sum+u.hours,0);
const extraHours=m.additionalWork.reduce((sum,u)=>sum+u.hours,0);
const link=(path,label)=>`<a href="${e(path)}">${e(label)}</a>`;
const section=(id,label,title,body)=>`<section id="${id}" class="programme-section"><p class="eyebrow">${label}</p><h2>${title}</h2>${body}</section>`;
const table=(caption,head,rows)=>`<div class="table-scroll" tabindex="0" role="region" aria-label="${e(caption)}"><table><caption>${e(caption)}</caption><thead><tr>${head.map(h=>`<th scope="col">${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((cell,i)=>i===0?`<th scope="row">${cell}</th>`:`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const footer=`<footer><a href="/identity/">LibraUni · Our identity</a><a class="licence-link" href="/license/"><span>Licence &amp; reuse</span><img src="/licenses/cc-by-nc-sa.svg" width="88" height="31" alt="CC BY-NC-SA 4.0 — course materials; exclusions apply"></a><span>Independent learning · Our awards are non-accredited.</span></footer>`;
const shell=(title,crumbs,body)=>`<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="${e(title)} — LibraUni curriculum design and module preview."><meta name="theme-color" content="#F7F4ED"><title>${e(title)} · LibraUni</title><link rel="icon" href="/brand/favicon.svg"><script>try{if(localStorage.getItem('librauni-theme')==='dark')document.documentElement.dataset.theme='dark'}catch{}</script><link rel="stylesheet" href="/src/style.css"><link rel="stylesheet" href="/src/identity.css"><link rel="stylesheet" href="/src/programme.css"></head>
<body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="/" aria-label="LibraUni home"><span class="lu-symbol" aria-hidden="true"><img src="/brand/librauni-symbol-transparent.png" alt="" width="864" height="524"></span><span>LibraUni</span></a><span class="header-label">INDEPENDENT STUDY · PHYSICS</span><div class="header-actions"><button id="theme-toggle" class="theme-button" aria-pressed="false">Dark mode</button><a class="button-link" href="/">Study desk</a></div></header><main id="main" class="programme-page"><nav class="breadcrumb" aria-label="Breadcrumb">${crumbs.join('<span aria-hidden="true">/</span>')}</nav>${body}${footer}</main><script type="module" src="/src/theme.js"></script></body></html>`;

const bridgePath=bridge.path;
const intro=(eyebrow,title,lead,status)=>`<section class="intro"><p class="eyebrow">${e(eyebrow)}</p><h1>${e(title)}</h1><p class="lead">${e(lead)}</p><p class="small">${e(status)}</p></section>`;
const moduleLinks=ids=>ids.map(id=>{const mod=stage1Modules.find(m=>m.code===id);return link(mod.path,mod.code+' · '+mod.title);}).join(' + ');
const semesterTable=table('Final Stage 1 structure',['Semester','Concurrent modules','Credits','Notional hours'],semesters.map(s=>[String(s.number),moduleLinks(s.codes),'60','600']));
const timing=`<p><strong>Semester timing:</strong> two sequential semesters, with two concurrent 30-credit modules in each. Each semester therefore contains 600 notional hours. Calendar weeks, holidays, start dates and assessment deadlines are not yet set; both modules in a pair will use a coordinated semester timetable. The superseded 30/31-week M100–A101 pairing is withdrawn. “Semester” does not silently reduce the required hours.</p>`;
const stage1Body=section('stage-1','02 / STAGE 1','One structure. Two balanced semesters.',`<p>${link('/programme/stage-1/map/','Stage 1 module map')}: outcomes, boundaries, workload and handovers.</p><p>Stage 1 has one fixed 120-credit structure. Each semester pairs a more abstract mathematics module with a more applied physics or astronomy module.</p>${semesterTable}<p><strong>Why this order:</strong> M101 and P101 first establish mathematical tools and physical reasoning together. M102 and A101 then extend the mathematics and apply the first semester’s foundations to astronomical investigations. A101 does not displace introductory physics.</p>${table('Stage 1 module roles',['Module','Role'],stage1Modules.map(m=>[link(m.path,m.code+' · '+m.title),e(m.purpose)]))}${timing}<h3 id="bridge">Optional preparation · outside the degree</h3><p>${link(bridge.path,'LU-M100 · '+bridge.title)} is available only if preparation is needed. Its 30 internal credits represent 300 hours and do not count towards the 120-credit stage or 360-credit degree. It combines mathematics with relevant physics applications and substantial Python work, progressing towards controlled AI/agent assistance. Abstract exercises remain where they build fluency.</p><p>Readiness evidence will determine whether the full bridge or selected refreshers are appropriate. Selected refreshers do not automatically earn the full module credit. Completing the full bridge plus Stage 1 would mean 1,500 hours in total; the degree itself remains 360 credits.</p><p><strong>Current next step:</strong> the Stage 1 module-level map is approved; M101’s four blocks and 13 units are approved; M101 and P101 blocks and units are approved; M102’s blocks and units are approved; A101’s blocks are approved; review its complete revised unit proposal next. Lesson production is on hold until the agreed blueprint gates are reviewed. No start date, exemption or enrolment has been created.</p>`);
let programme=fs.readFileSync(root+'programme/index.html','utf8');
programme=programme.replace(/<section id="stage-1"[\s\S]*?(?=<section id="stage-2")/,stage1Body+'\n');
programme=programme.replace(/PHYSICS \/ PROGRAMME BLUEPRINT [0-9.]+/,'PHYSICS / PROGRAMME BLUEPRINT 1.0');
programme=programme.replace(/<p class="small">(?:Draft for discussion|Route architecture revised)[\s\S]*?<\/p>/,'<p class="small">Stage 1 architecture confirmed · 24 September 2026 · Module details and teaching materials remain in development.</p>');
programme=programme.replace(/<p class="notice">[\s\S]*?<\/p>/,`<p class="notice">Stage 1 is fixed: M101 + P101, then M102 + A101. ${link(bridge.path,'M100 is the optional bridge outside the degree')}. The programme-wide blueprint audit now precedes lesson production. The ${link('/programme/coverage/','coverage register')} retains unresolved subject allocations.</p>`);
const blueprintBody=section('blueprint-audit','BLUEPRINT REVIEW / '+blueprint.date,'Plan the whole. Develop one piece at a time.',`<p>Our ${link('/programme/construction-policy/','public construction commitment')} sets the recursive conditions for planning, authoring and release.</p><p>Architecture, module scope and available teaching are different states. This audit records what exists and what remains to be designed. Lesson production is on hold while the blueprint is reconciled.</p>${table('Blueprint inventory',['Scope','Current evidence','Required next detail'],blueprint.inventory.map(row=>row.map(e)))}<h3>Dependencies to resolve</h3>${table('Progression decisions — not approved unit allocations',['Connection','Design requirement'],blueprint.dependencies.map(row=>row.map(e)))}<h3>Before the first teaching section</h3><ol>${blueprint.gates.map(g=>`<li>${e(g)}</li>`).join('')}</ol><p><strong>Current review:</strong> ${link('/programme/stage-1/map/','Stage 1 module-level map')}. After review, develop M101 Mathematics for physics I through Block and Unit level, with explicit handovers to concurrent P101. Review each proposal before proceeding to the next module.</p><p>The existing MIT/Imperial comparison remains preliminary. Analytical mechanics, solid-state and nuclear/particle foundations, probability and practical access remain visible in the ${link('/programme/coverage/','coverage register')}. This inventory is not a new equivalence audit. Credits, enrolment and saved timetables are unchanged.</p>`);
programme=programme.replace(/<section id="blueprint-audit"[\s\S]*?<\/section>/,'');
programme=programme.replace('<section id="stage-2"',blueprintBody+'\n<section id="stage-2"');
if(!programme.includes('href="#blueprint-audit"')) programme=programme.replace('<a href="#architecture">','<a href="#blueprint-audit">Blueprint review</a><a href="#architecture">');
fs.writeFileSync(root+'programme/index.html',programme);

const bridgeBody=intro('OPTIONAL PREPARATION / LU-M100',bridge.title,bridge.purpose,'30 internal credits · 300 notional hours · Outside the degree · Scope & completion policy approved')+`<p class="notice">This is the former mathematical-foundations module, now M100. It is not a Stage 1 option and is not paired with A101. Its three-block organisation is confirmed. All three block scopes and their workload allocations are approved. The whole-module review maps planned evidence below; the completion policy is approved. Task-level marking guides, tool feasibility and teaching release remain open.</p><nav class="programme-nav" aria-label="Bridge sections">${[['place','Role'],['blocks','Blocks'],['block-1-review','Block 1 review'],['block-2-review','Block 2 review'],['block-3-review','Block 3 review'],['module-review','Whole-module review'],['completion-rubric','Completion rubric'],['preparing-to-study','Preparing to study'],['exit-standard','Exit standard'],['units','Unit outline'],['computing','Python & AI'],['assessment','Assessment'],['study-planner','Provisional planner']].map(([id,t])=>link('#'+id,t)).join('')}</nav>`+
section('place','01 / PREPARATION','Catch up where needed.',`<p>${e(m.entry)}</p><p>${e(m.exit)}</p><p>The full bridge must justify its 300 hours through mathematical fluency, meaningful physics applications and a thorough scientific Python refresher. Begin with learner-written code, then introduce AI suggestions and bounded coding agents while retaining specification, understanding, independent testing, review and control. No diagnostic or exemption has been awarded.</p>${table('Retained learning outcomes',['Outcome','What completion should demonstrate'],m.outcomes.map(([id,t,d])=>[e(id+' · '+t),e(d)]))}`)+
section('blocks','02 / BLOCKS','Three connected steps.',`<p>Module → Block → Unit → Lesson. Blocks organise learning; they do not add credits, enrolments or separate assessments. Their hours are the sum of their units; module-wide work is budgeted separately.</p>${table('M100 blocks',['Block','Units','Unit hours','Purpose'],m.blocks.map(b=>[link('#'+b.id,b.id+' · '+b.title),b.units.map(id=>link('#'+id,id)).join(', '),String(m.units.filter(u=>b.units.includes(u.id)).reduce((n,u)=>n+u.hours,0)),e(b.purpose)]))}`)+
section('exit-standard','03 / COMPLETION & EXIT STANDARD','Ready to begin mathematical physics.',`<p><strong>Agreed completion principles:</strong> demonstrate every essential capability, assess independent work separately from controlled assistance, and gather evidence through the existing TMAs and combined EMA within 300 hours. The capability descriptors below are made concrete by the approved completion rubric. An overall mark should not conceal a substantial gap in algebra or independent programming. These checks must be embedded within the existing assessment/revision budget, not added as an extra examination.</p>${table('M100 exit standard',['Capability','What you should be able to do','Evidence'],m.exitStandard.map(([id,t,os,d,ev])=>[e(id+' · '+t),e(d),e(ev)]))}<p>Separate independent fluency from assisted investigation. Documentation is allowed for the independent programming task; generated solutions and tutor-led answers are not. AI assistance may be used only where an assessment explicitly permits it and must be acknowledged. The completion rubric below defines criteria and targeted reassessment; task-specific marking guides remain to be written. No diagnostic, readiness decision or award has been made.</p><p>Boundary: prepare for calculus without teaching its formal methods here. Physical relationships used in bridge problems are explained or supplied; the systematic development of physical laws belongs to P101. Advanced software engineering and agent development are outside this bridge.</p>`)+
section('block-1-review','BLOCK 1 / DESIGN REVIEW','Calculate and express relationships.',`<p class="notice">${e(block1.status)}. Unit scope and the independent Python component of TMA 01 are agreed. Workload allocations remain design estimates; lesson content and assessment questions are not yet available.</p><p>${e(block1.purpose)}</p>${table('Block 1 approved workload — hours included, not additional',['Unit',...block1.workloadLabels,'Total'],block1.units.map(u=>[link('#'+u.id,u.id),...u.hours.map(String),String(u.hours.reduce((a,b)=>a+b,0))]))}<p>80 unit hours, including 14 hours of Python. Categories are mutually exclusive for budgeting; a Python activity may also practise mathematics.</p>${block1.units.map(u=>`<article class="unit-card"><h3>${e(u.id+' · '+m.units.find(x=>x.id===u.id).title)}</h3><h4>Teaching sequence</h4><ol>${u.sequence.map(t=>`<li>${e(t)}</li>`).join('')}</ol><dl>${[['Practice progression',u.practice],['Physical investigation',u.investigation],['Independent evidence',u.evidence],['Misconceptions to address',u.pitfalls],['Planned visual explanations',u.visuals],['Preparation for what follows',u.forward]].map(([t,d])=>`<dt>${t}</dt><dd>${e(d)}</dd>`).join('')}</dl></article>`).join('')}<h3>Assessment and a responsive refresher</h3><p>${e(block1.assessment)}</p><p>${e(block1.readiness)}</p><h3>Fit within the programme</h3><p>${e(block1.coherence)}</p><p>${e(block1.limitations)}</p><p class="small">Scope check, 24 September 2026: <a href="https://ocw.mit.edu/courses/18-01sc-single-variable-calculus-fall-2010/pages/syllabus/">MIT 18.01SC’s historical syllabus</a> names algebra and trigonometry as calculus prerequisites. This supports the bridge’s preparatory role, not equivalence or approval of these hours. The full two-university coverage audit remains in the <a href="/programme/coverage/">coverage register</a>.</p>`)+
section('block-2-review','BLOCK 2 / DESIGN REVIEW','Understand functions and models.',`<p class="notice">${e(block2.status)}. The approved redistribution is applied to the module outline and planner workload estimates; saved dates remain unchanged. Lessons and assessment questions remain unavailable.</p><p>${e(block2.budget)}</p>${table('Block 2 approved workload — hours included, not additional',['Unit','Current total',...block2.workloadLabels,'Approved total'],block2.units.map(u=>[link('#'+u.id,u.id),String(m.units.find(x=>x.id===u.id).hours),...u.hours.map(String),String(u.hours.reduce((a,b)=>a+b,0))]))}${block2.units.map(u=>`<article class="unit-card"><h3>${e(u.id+' · '+m.units.find(x=>x.id===u.id).title)}</h3><h4>Teaching sequence</h4><ol>${u.sequence.map(t=>`<li>${e(t)}</li>`).join('')}</ol><dl>${[['Practice progression',u.practice],['Physical investigation',u.investigation],['Independent evidence',u.evidence],['Misconceptions to address',u.pitfalls],['Planned visual explanations',u.visuals],['Preparation and boundaries',u.forward]].map(([t,d])=>`<dt>${t}</dt><dd>${e(d)}</dd>`).join('')}</dl></article>`).join('')}<h3>Assessment and timetable</h3><p>${e(block2.assessment)}</p><p>${e(block2.timing)}</p><h3>Fit within the programme</h3><p>${e(block2.coherence)}</p><p class="small">This is original curriculum design informed by the existing <a href="/programme/coverage/">coverage register</a>. Detailed exercise calibration and workload validation remain open; no institutional equivalence or exact OU weekly match is claimed.</p>`)+
section('block-3-review','BLOCK 3 / DESIGN REVIEW','Investigate and explain.',`<p class="notice">${e(block3.status)}. The hands-on agent placement in U12 and EMA assistance rules below are approved. No lessons or assessment questions are released.</p><p>${e(block3.budget)}</p>${table('Block 3 approved workload — hours included, not additional',['Unit',...block3.workloadLabels,'Total'],block3.units.map(u=>[link('#'+u.id,u.id),...u.hours.map(String),String(u.hours.reduce((a,b)=>a+b,0))]))}${block3.units.map(u=>`<article class="unit-card"><h3>${e(u.id+' · '+m.units.find(x=>x.id===u.id).title)}</h3><h4>Teaching sequence</h4><ol>${u.sequence.map(t=>`<li>${e(t)}</li>`).join('')}</ol><dl>${[['Practice progression',u.practice],['Physical investigation',u.investigation],['Evidence',u.evidence],['Misconceptions to address',u.pitfalls],['Planned visual explanations',u.visuals],['Preparation and boundaries',u.forward]].map(([t,d])=>`<dt>${t}</dt><dd>${e(d)}</dd>`).join('')}</dl></article>`).join('')}<h3>Assessment and assistance</h3><p>${e(block3.assessment)}</p><p>${e(block3.assistance)}</p><h3>Workload and programme fit</h3><p>${e(block3.timing)}</p><p>${e(block3.coherence)}</p>`)+
section('units','04 / UNIT OUTLINE','Mathematics with a clear purpose.',`<p>These twelve draft units total 240 hours. Their detailed scope and distribution will be reviewed next as M100; this publication does not silently approve the previous design.</p>${table('M100 unit map',['Unit','Hours','Role'],m.units.map(u=>[link('#'+u.id,u.id+' · '+u.title),String(u.hours),e(u.can)]))}${m.units.map(u=>`${m.blocks.filter(b=>b.units[0]===u.id).map(b=>`<h3 id="${b.id}">${e(b.id+' · '+b.title)}</h3><p>${e(b.purpose)}</p>`).join('')}<article class="unit-card" id="${u.id}"><p class="eyebrow">${u.id} · ${u.hours} HOURS · DRAFT</p><h3>${e(u.title)}</h3><p>Preparation: ${u.requires.map(id=>link('#'+id,id)).join(', ')||'Module entry readiness'}.</p><dl>${[['Scope',u.scope],['By the end',u.can],['Computing',u.computing],['Physics context',u.context],['Evidence',u.evidence],['Boundary',u.boundary]].map(([t,d])=>`<dt>${e(t)}</dt><dd>${e(d)}</dd>`).join('')}</dl></article>`).join('')}`)+
section('computing','05 / SCIENTIFIC PROGRAMMING','Write, understand, verify and control.',`<p>The approved allocation contains 48 integrated computing hours inside the 240 unit hours, not in addition to them. Use physics when it supports understanding and abstract practice when it supports fluency.</p>${table('Retained programming progression',['Unit','Hours within unit','Focus','Practice'],computing.map(([id,h,t,d])=>[link('#'+id,id),String(h),e(t),e(d)]))}<p>Required tools must be free. Distinguish unaided programming evidence, supported learning and permitted AI assistance. A supplied agent trace supports critique but is not evidence of operating an agent. Generated code that runs does not establish understanding.</p>`)+
section('module-review','WHOLE MODULE / DESIGN AUDIT','How the pieces fit together.',`<p>Reviewed ${e(audit.date)}. All three block scopes are approved. This review checks planned learning and assessment; it is not evidence of learner mastery or a claim of institutional equivalence.</p>${table('Whole-module coherence checks',['Check','Finding'],audit.checks.map(r=>r.map(e)))}<h3>Where each capability is demonstrated</h3><p>This is the assessment blueprint for detailed rubric design. Sample tasks across the existing assignments, without adding an examination or forcing every topic into one notebook. Essential capabilities require explicit evidence; an aggregate score cannot conceal a gap.</p>${table('Planned capability evidence',['Capability','Teaching and practice','Evidence home','Required evidence focus'],audit.evidence.map(r=>r.map(e)))}<h3>What remains before teaching</h3>${table('Open design and release decisions',['Decision','Required next step'],audit.open.map(r=>r.map(e)))}<p>See the <a href="/programme/coverage/">degree coverage register</a> for later subject homes and unresolved breadth/depth questions.</p>`)+
section('completion-rubric','COMPLETION / APPROVED POLICY','Evidence of understanding.',`<p class="notice">${e(rubric.status)}. The completion principles, detailed criteria and reassessment policy below are approved. They do not change grades, progress or dates.</p><p>${e(rubric.principle)}</p>${table('Evidence judgements',['Judgement','Meaning'],rubric.levels.map(r=>r.map(e)))}${rubric.capabilities.map(c=>`<article class="unit-card"><h3>${e(c.id+' · '+c.title)}</h3><ul>${c.criteria.map(([id,t])=>`<li><strong>${e(id)}</strong> · ${e(t)}</li>`).join('')}</ul><p><strong>Evidence:</strong> ${e(c.home)}</p><p><strong>When follow-up is needed:</strong> ${e(c.gap)}</p></article>`).join('')}<h3>Completing the full bridge</h3><ol>${rubric.completion.map(t=>`<li>${e(t)}</li>`).join('')}</ol><h3>Permitted assistance</h3>${table('Assistance and independence',['Work','Conditions'],rubric.assistance.map(r=>r.map(e)))}<h3>Feedback, practice and reassessment</h3><ol>${rubric.recovery.map(t=>`<li>${e(t)}</li>`).join('')}</ol><h3>Private evidence and task release</h3><p>${e(rubric.record)}</p><p>${e(rubric.release)}</p>`)+
section('preparing-to-study','PREPARATION / WHAT COMES NEXT','From an approved design to usable teaching.',`<p>M100’s scope and completion policy are settled. Teaching preparation now needs evidence about entry readiness, a working Python environment and carefully checked materials. These steps do not enrol you or start a deadline.</p><h3>1 · Establish a starting point</h3><p>Begin with a short, non-graded readiness conversation and a small sample of independent mathematics and Python. Separate conceptual understanding from forgotten notation or syntax, and record confidence separately from accuracy. A sample can identify where to begin; it cannot establish mastery of an entire 300-hour module. Existing qualifications are context, not automatic exemption.</p><p>Use that evidence to recommend either the full bridge or a clearly scoped refresher plan. If bypassing M100 is considered, review all relevant entry requirements with sufficient evidence rather than infer readiness from a few easy questions. Selected refreshers do not earn the full module credit. Initial readiness and basic computing setup belong within the existing six-hour orientation allowance; additional checking must be recorded honestly.</p><h3>2 · Verify the practical environment</h3><p>Before teaching begins, check the learner’s preferred working environment and existing Python installation. Teach the setup step by step, assuming only very basic Python familiarity. The existing six-hour orientation reserves three hours for guided VS Code/Python/Jupyter setup, one for notebook and backup practice, one for navigation/files and one for initial readiness. U01 then teaches Python foundations within its four integrated computing hours. Verify saving, reopening and rerunning a small file. Later, before U12 release, verify a genuinely free bounded-agent workflow, diff review and rollback on the learner’s machine. No software is installed by this preview; access to a paid tutor service is not a substitute for a free required course tool.</p><h3>3 · Prepare and release incrementally</h3><p>Complete the agreed Stage 1 design/readiness review, then author the first authorised section inside its lesson, unit and block. Check mathematics, code, figures, practice, feedback and workload before release. Prepare task-specific marking guides and private submission arrangements before assessed work. Keep later content at outline level until its turn; do not fill the whole module with unreviewed lessons.</p><p>Enrolment and start dates remain explicit learner choices. Calendars will use the shared planner and preserve manual adjustments; they will not treat elapsed dates as demonstrated learning.</p>`)+
section('assessment','06 / WORKLOAD & EVIDENCE','A reconciled 300-hour budget.',`${table('M100 provisional workload',['Component','Hours','Included work'],[['Unit work','240','Reading, examples, mathematical practice, computing and embedded checkpoints.'],...m.additionalWork.map(w=>[e(w.name),String(w.hours),e(w.detail)]),['Total','300','Outside the degree allocation.']])}${table('Retained assessment mapping',['Assessment','Units','Outcomes'],m.assessment.map(a=>[e(a.name),a.units.join(', '),a.outcomes.join(', ')]))}<p>The approved structure has three TMAs, three embedded iCMAs and one combined EMA. The approved EMA assistance rules are stated above. Task-specific marking guides and private submission arrangements remain to be prepared. Assess understanding independently; no grade or credit follows from page completion.</p>`)+
`<section id="study-planner" class="programme-section" data-planner="LU-M100"><h2>Optional bridge planner</h2><p>Loading your planner…</p></section><script type="module" src="/src/planner.js"></script><p>The bridge’s old 30-study-week estimate is retained solely as a provisional preparation plan subject to workload calibration during authoring. It is not a Stage 1 semester duration or a verified exact OU timetable.</p>`;
const a101BlockBody=section('blocks','A101 / APPROVED BLOCKS','A practical astronomy module built on Semester 1.',`<p>${e(a101Blocks.status)} · ${e(a101Blocks.date)}. Four approved blocks preserve the ten unit IDs. The revised individual unit map below awaits review.</p>${table('Approved A101 blocks',['Block','Inherited unit IDs','Study hours','Python included'],a101Blocks.blocks.map(b=>[link('#'+b.id,b.id+' · '+b.title),e(b.units.join(', ')),String(b.hours),String(b.pythonHours)]))}<p><strong>30 + 78 + 56 + 76 = 240 study hours, including 78 Python hours.</strong> Add orientation 6, TMAs 18, EMA 18, revision 12 and feedback 6 = 300. Astronomical workflow orientation replaces generic Python setup. Required examples, practice and investigations fit inside these hours.</p><p>Compared with the inherited outline, introductory U01–U02 contracts from 36 to 30 hours; imaging U03–U05 from 82 to 78; spectra/variability U06–U07 grows from 50 to 56; distance/populations/synthesis U08–U10 from 72 to 76. The block reallocations are approved; the proposed individual unit budgets appear below.</p>${a101Blocks.blocks.map(b=>`<article class="unit-card" id="${b.id}"><h3>${e(b.id+' · '+b.title)}</h3><p>${b.hours} hours, including ${b.pythonHours} Python hours. Prior blocks: ${e(b.requires.join(', '))||'Semester 1 readiness'}. Outcomes: ${e(b.outcomes.join(', '))}.</p><dl>${[['Purpose',b.purpose],['Scope',b.scope],['Boundaries',b.boundary],['Python',b.python],['Investigation and deliverable',b.practical],['Evidence',b.evidence],['Prerequisites and handover',b.handover]].map(([t,d])=>`<dt>${e(t)}</dt><dd>${e(d)}</dd>`).join('')}</dl></article>`).join('')}<p><strong>Recursive gate:</strong> approved Stage 1 peer scopes and M101/P101/M102 unit maps support block construction. Block approval permits unit blueprinting. The revised unit map below is proposed. No lessons, dates or enrolment are released. Next: review all ten units and the Stage 1 checkpoint. ${link('/programme/construction-policy/','Policy 1.0')} remains binding.</p><p>Free local Python/NumPy/Matplotlib plus selected Astropy helpers form the planned toolset. Small documented Gaia/TESS subsets are candidates; data rights, flags, release versions, accessibility and complete activity runs remain release checks. Optional telescope work is not required. Simulations/data analysis do not establish apparatus or teamwork skills.</p><ol class="source-list">${a101Blocks.sources.map(([t,url,n])=>`<li>${link(url,t)}<p>${e(n)}</p></li>`).join('')}</ol><p>Public record: <a href="https://github.com/LibraUni/librauni.github.io/blob/main/docs/a101-block-review.md">A101 block revision review</a>.</p>`);
const aBody=intro('STAGE 1 / SEMESTER 2 / LU-A101',a101.title,a101.purpose,'30 internal credits · 300 notional hours · Alongside M102 · Blocks approved · Revised units proposed')+`<p class="notice">A101 belongs in Semester 2 after M101 and P101. The earlier first-module pairing, beginner readiness gates and 31-week timetable are withdrawn. The complete revised unit proposal below replaces the earlier individual hour allocations; unit IDs are preserved.</p>`+
section('place','01 / POSITION','Apply the first semester’s foundations.',`<p>${e(a101.entry)}</p><p>${link('/programme/stage-1/lu-m102/','M102 · Mathematics for physics II')} is the concurrent mathematical partner. A101 should apply established mathematics and physics, teach new astronomical methods explicitly, and avoid repeating M100 preparation. Its assessment dates will be coordinated with M102.</p>${timing}`)+
section('outcomes','02 / OUTCOMES','Evidence from astronomical observations.',table('Draft astronomical outcomes',['Outcome','Evidence'],a101.outcomes.map(([id,t,d])=>[e(id+' · '+t),e(d)])))+
a101BlockBody+section('units','03 / SUBJECT OUTLINE','Ten connected astronomical investigations.',`<p>${e(a101.status)} · version ${e(a101.version)} · ${e(a101.date)}. All ten units now reconcile with the approved block budgets. Prior A101 units specify the study sequence; named Semester 1 units identify required tools. No required M102 unit or compulsory M100 prerequisite exists.</p>${table('A101 subject map',['Unit','Block','Study hours','Python included'],a101.units.map(u=>[link('#'+u.id,u.id+' · '+u.title),link('#'+u.block,u.block),String(u.hours),String(u.pythonHours)]))}${a101.units.map(u=>`<article class="unit-card" id="${u.id}"><h3>${u.id} · ${e(u.title)}</h3><p>${u.hours} hours, including ${u.pythonHours} Python hours · ${u.requires.length?'Earlier A101 units: '+u.requires.map(id=>link('#'+id,id)).join(', '):'Semester 1 readiness'}.</p><p>Required Semester 1 units: ${u.entryUnits.map(ref=>{const [code,id]=ref.split(':');return link('/programme/stage-1/lu-'+code.toLowerCase()+'/#'+id,code+' '+id);}).join(', ')}.</p><dl>${[['Scope',u.scope],['Investigation',u.activity],['Computing',u.computing],['Evidence',u.evidence],['Validation and deliverable',u.validation],['Boundary',u.boundary],['Forward handover',u.handover]].map(([t,d])=>`<dt>${e(t)}</dt><dd>${e(d)}</dd>`).join('')}</dl></article>`).join('')}`)+
section('assessment','04 / ASSESSMENT','Methods and conclusions, not just outputs.',`${table('Retained assessment proposal — dates withdrawn',['Assessment','Preparation','Outcomes','Evidence'],a101.assessments.map(a=>[e(a.name),a.requires.join(', '),a.outcomes.join(', '),e(a.evidence)]))}<p>Workload: 240 unit hours, including 78 Python hours and three one-hour iCMAs in U02/U05/U09; orientation 6, TMAs 18, EMA 18, revision 12 and feedback 6 = 300 hours. Orientation concerns astronomy files, metadata and the existing workflow, not repeated Python installation. ${e(a101.independentAssessment)} No live timetable or assessment submission is available. Assessment formats and hours remain draft until the Semester 2 design is reviewed.</p>`)+
section('practical','05 / PRACTICAL WORK','Reproducible astronomical investigations.',`<p>Use small, documented local datasets: curated Gaia catalogues, TESS light curves and selected image/spectral cutouts. Planned tools are Python notebooks, NumPy, Matplotlib and selected Astropy helpers. Check provenance, units, data quality, assumptions and limiting cases; show independent calculations and explain any AI-assisted code changes.</p><p>Verify current free access, dataset rights and acknowledgements, a compatible pinned environment and an offline workflow before release. No telescope, paid AI account or GPU is required. Computational work does not certify instrument-handling experience. Advanced orbital dynamics, stellar structure, galactic dynamics and cosmology remain later study.</p>`)+
section('stage-checkpoint','STAGE 1 / BLUEPRINT CHECKPOINT','The whole stage is outlined; teaching gates remain.',`<p>M101 has 13 approved units, P101 13, M102 14 and A101 now proposes 10: 50 units across the fixed four-module stage. Study hours total 960, plus 240 orientation/assessment/revision/feedback hours = 1,200 hours / 120 internal credits. Included Python totals 190 hours (30 + 48 + 34 + 78), not additional workload.</p><p>Semester 1 logical handovers are mapped; Semester 2 required A101 work uses completed Semester 1 units. Optional M102 enrichment must follow readiness and replace a bounded example within its allocation, not add hidden requirements. No live calendar or enrolment is created.</p><p><strong>Remaining gates:</strong> review A101 units; verify referenced OU presentation durations and joint assessment calendars; complete the later-stage progression/core-coverage audit and fuller second-university evidence; blueprint every lesson in M100 Block 1 and all sections of its opening lesson. Datasets, tools, assessment rubrics and accessible runnable activities remain release work. The ${link('/programme/coverage/','coverage register')} retains depth and apparatus/teamwork limitations.</p><p>Current construction disposition: policy 1.0 permits A101 unit blueprinting because its blocks and Stage 1 peer scope are approved. Unit approval pending; teaching not released. Record: <a href="https://github.com/LibraUni/librauni.github.io/blob/main/docs/a101-unit-review.md">A101 unit and Stage 1 review</a>.</p>`)+
section('review','06 / SOURCES & NEXT STEPS','Scope evidence, not an inherited timetable.',`<p>The first-module pacing has been removed. Reassess density, prerequisites and practical depth for Semester 2 alongside M102. No start date or enrolment has been set. Review the ${link('/programme/stage-1/map/#a101','proposed A101 role and Stage 1 handovers')} first. M101, P101 and M102 unit maps are approved. A101 blocks are approved and the complete revised units await review. The Stage 1 checkpoint below identifies the remaining work.</p><ol class="source-list">${a101Sources.map(([t,u,n])=>`<li>${link(u,t)}<p>${e(n)}</p></li>`).join('')}</ol>`);
const coverageBody=intro('PHYSICS / COVERAGE REGISTER','Keep every subject in view.','Map foundations, core physics and specialist depth to units and assessed evidence.','Updated for the final Stage 1 structure · 24 September 2026')+
section('architecture','01 / STRUCTURE','Preparation is separate from degree coverage.',`${semesterTable}<p>M100 is optional preparation outside Stage 1. Its presence cannot substitute for the degree’s mathematical or physical outcomes. Earlier route choices and concurrent M100–A101 readiness gates have been removed. ${link('/programme/','Programme architecture')}</p>`)+
section('matrix','02 / COVERAGE','Proposed homes and unresolved depth.',table('Coverage register',['Subject','Benchmarks','Destination','Status / action'],coverage.map(([id,t,r,d,s,a])=>[`<span id="${id}">${e(id+' · '+t)}</span>`,e(r),e(d),`<strong>${e(s)}</strong><br>${e(a)}`])))+
section('gaps','03 / OPEN DECISIONS','No gap is closed by renaming a module.',gaps.map(g=>`<article class="unit-card"><h3>${e(g.id+' · '+g.title)}</h3><p>${e(g.decision)}</p><p>Rows: ${g.rows.map(id=>link('#'+id,id)).join(', ')}.</p></article>`).join(''))+
section('sources','04 / REFERENCES','Evidence and its limits.',`<p>This is a subject-level comparison, not an institutional-equivalence claim. Detailed units, prerequisites, hours and assessment evidence must justify coverage. Historical and indexed-only sources are identified below.</p><ol class="source-list">${sources.map(s=>`<li id="source-${s.id}">${e(s.id)} · ${link(s.url,s.name)}<p>${e(s.note)}</p></li>`).join('')}</ol>`);
const policyBody=intro('PHYSICS / PUBLIC COMMITMENT','Coherence by construction.','Every teaching section belongs to a larger purpose. We commit to planning the surrounding structure before developing its details, and to reviewing the whole when those details reveal a problem.',`Adopted ${policy.date} · Policy ${policy.version}`)+
section('principle','01 / PRINCIPLE','Plan before elaborating.',`<p><strong>${e(policy.principle)}</strong></p><p>Our hierarchy is Degree → Stage → Module → Block → Unit → Lesson → Section. Blueprinting specifies a component’s purpose, structure and interfaces; authoring produces its explanations, examples, activities and feedback. These are separate activities: planning all lessons is not writing all lessons.</p><p>This commitment applies whenever we construct, revise or release curriculum and teaching materials. It is a working review policy, not a claim that software tests can certify educational quality.</p>`)+
section('conditions','02 / CONSTRUCTION CONDITIONS','A clear threshold at every level.',table('Recursive construction conditions',['To begin…','Required surrounding blueprint'],policy.gates.map(row=>row.map(e)))+`<p>“Every” refers to the named enclosing scope, not the whole degree. Every lesson in a block means lessons in all its units. Distant stages may retain explicitly provisional maps; their current purposes, boundaries and interfaces must still be clear. We do not need every final-stage lesson before writing an introductory section.</p><p>The optional M100 bridge sits outside the degree. Apply its lesson, unit and block conditions normally; use its entry-preparation role and the receiving Stage 1 as the wider context. This does not place M100 inside Stage 1 or count its credits towards the degree.</p>`)+
section('blueprint','03 / BLUEPRINT CONTENT','More than a list of titles.',table('Minimum blueprint information at the relevant resolution',['Field','Required information'],policy.fields.map(row=>row.map(e)))+`<p>Use identifiers and explicit links where available. A proposed map, an approved scope and released teaching must remain visibly different states. Unknowns must be recorded; a gap relevant to the proposed work cannot be labelled complete simply to pass a gate.</p>`)+
section('dependencies','04 / DEPENDENCIES & CHANGE','Follow the consequences.',`<p><strong>Dependencies can require more detail than the minimum.</strong> If a physics unit uses mathematics from a concurrent module, identify the teaching component, required outcome and order of availability. A broad module title does not settle the dependency.</p><p><strong>Changes trigger a review of affected components.</strong> When drafting reveals a missing prerequisite or unrealistic workload, update the blueprint and check its parent, peers, predecessors and successors. Review Section → Lesson → Unit → Block → Module → Stage → Degree, in greater detail close to the work and more broadly farther away. Record the impact on coverage, assessment and hours; do not quietly insert unbudgeted teaching or alter saved timetables.</p><p>If a construction condition is not met, return to planning the missing structure. Exploratory notes can inform that plan; they must not be presented as approved or released teaching. Preserve prior versions and record the reason for a policy or scope revision.</p>`)+
section('release','05 / RELEASE','Construction readiness is not publication readiness.',`<p>A component can pass its construction gate and still need revision before publication. Release review checks scientific and mathematical accuracy, code behaviour, prerequisites, incremental pedagogy, worked examples, exercises and feedback, figures and captions, accessibility, free references and reuse rights, workload and assessment alignment. Apply checks relevant to the piece; document any unresolved issue.</p><p>For each construction or material revision, retain a concise review record: component and parent; policy version and applicable gate; links to surrounding blueprints; dependency and budget checks; construction disposition; separate release disposition; evidence, unresolved issues and forward handover. Date the review and identify the actual reviewer without implying independent review that did not occur. Generic records belong with public curriculum sources; personal learning evidence remains private.</p>`)+
section('current','06 / CURRENT APPLICATION','A stronger starting condition.',`<p>Before the first M100 teaching section, our agreed starting threshold additionally requires Stage 1 block-and-unit blueprints, a review of later-stage progression, every lesson across M100 Block 1, and every section in its opening lesson. Existing orientation tutoring does not replace those blueprints or bypass the condition.</p><p>See the ${link('/programme/#blueprint-audit','current blueprint audit')} for actual planning status and next decisions, and the ${link('/programme/coverage/','coverage register')} for unresolved subject homes and depth. The existence of this policy does not mean those conditions have already been satisfied.</p>`);
const mapBody=intro('PHYSICS / STAGE 1 / MODULE MAP','Four modules. One connected foundation.','The approved division of teaching responsibilities, outcomes and evidence before detailed blocks and units are designed.',`${stageMap.status} · Version ${stageMap.version} · ${stageMap.date}`)+
`<nav class="programme-nav" aria-label="Stage 1 map sections">${[['context','Stage progression'],['entry','Entry'],...stageMap.modules.map(mod=>[mod.anchor,mod.code]),['workload','Workload'],['ownership','Teaching responsibilities'],['handover','Handovers'],['review','Decisions'],['sources','Sources']].map(([id,label])=>link('#'+id,label)).join('')}</nav>`+
section('context','01 / WIDER CONTEXT','Build towards the next stage.',table('Provisional stage exit expectations',['Stage','Intended exit','Progression and boundaries'],stageMap.stages.map(row=>row.map(e)))+`<p>The 360-credit structure remains unchanged. Optional M100 is outside those credits. This page records approved module-level outcomes and responsibilities; it does not approve blocks, units, assessment tasks or teaching release. Our ${link('/programme/construction-policy/','construction policy')} remains the governing condition.</p>`)+
section('entry','02 / ENTRY','Readiness without a hidden bridge requirement.',`<p>${e(stageMap.entry)}</p><p>Evidence-based retrieval can shorten repeated practice for a prepared learner; it does not automatically award a module’s credits. Module orientation is budgeted below. Additional remedial work is recorded separately when it exceeds those hours.</p>`)+
stageMap.modules.map(mod=>{const base=stage1Modules.find(x=>x.code===mod.code);return section(mod.anchor,`SEMESTER ${base.semester} / ${mod.code}`,base.title,`<p class="lead">${e(mod.role)}</p><p><strong>Entry:</strong> ${e(mod.entry)}</p>${table('Approved module-level exit outcomes',['Outcome','Expected capability'],mod.outcomes.map(row=>row.map(e)))}<dl><dt>First teaching and responsibility</dt><dd>${e(mod.owns)}</dd><dt>Boundaries and later depth</dt><dd>${e(mod.boundary)}</dd><dt>Python and practical work</dt><dd>${e(mod.computing)}</dd><dt>Assessment role</dt><dd>${e(mod.evidence)}</dd><dt>Forward handover</dt><dd>${e(mod.handover)}</dd></dl><p>30 internal credits / 300 hours. Proposed final assessment: ${e(mod.final)}; detailed format and timing await module review. ${link(base.path,'Existing module preview')}</p>`);}).join('')+
section('workload','03 / WORKLOAD','A budget, not a promise of unmeasured capacity.',table('Proposed envelope for each 30-credit module',['Work','Hours'],stageMap.workload.map(([name,hours])=>[e(name),String(hours)]))+`<p><strong>240 + 6 + 18 + 18 + 12 + 6 = 300 hours per module; 600 per semester pair; 1,200 for Stage 1.</strong> This is an original provisional envelope, retaining A101’s existing draft total, not a verified OU week-by-week schedule. Explanation, worked examples, required exercises, Python and embedded iCMAs belong within the 240 study hours, not on top. Extra backup practice is optional unless explicitly budgeted as required.</p><p>The final-assessment allowance includes the task, instructions and required preparation/submission steps, including scan checks for handwritten work. The separate revision allowance covers broader consolidation, not duplicate task preparation. Module reviews must test whether each assessment fits. The common envelope may be redistributed within 300 hours with an explicit decision; it does not assert equal practical intensity.</p><p>P101 owns shared computing induction; M101’s orientation covers its own mathematical workflow. A101 orientation covers astronomy-specific data conventions rather than another generic Python installation course. Exact computing hours and topic budgets will be set in module reviews. Dates, semester lengths, final exam arrangements and assessment identifiers are not created here.</p>`)+
section('ownership','04 / TEACHING RESPONSIBILITY','Introduce once. Revisit with a purpose.',table('First teaching and subsequent development',['Strand','Primary home','Reuse and extension'],stageMap.ownership.map(row=>row.map(e))))+
section('handover','05 / DEPENDENCIES','Tools before the tasks that need them.',table('Proposed outcome-level handovers',['ID','Connection','Ordering requirement'],stageMap.interfaces.map(row=>row.map(e)))+`<p>These are logical constraints, not a dated timetable. Map each to actual block/unit IDs and assessment prerequisites when those outlines exist. No assessment may assume a concurrent-module skill merely because both modules have started.</p>`)+
section('review','06 / REVIEW DECISIONS','What this proposal settles—and what it does not.',`<p>Approved at module-map level: the outcome split, P101’s shared computing/measurement responsibility, M102’s explicit probability foundation, the provisional workload envelope, and written finals for the two mathematics modules versus EMAs for P101/A101.</p><p><strong>Capacity risks remain:</strong> P101 combines foundational physics and a first computing strand; M102 combines substantial mathematical methods and probability. Their detailed blocks/units must demonstrate that this fits. If it does not, reallocate scope visibly within the degree before approval; do not silently increase hours or remove required foundations. A101’s existing unit scopes need review for depth after Semester 1; this map does not approve them unchanged.</p><p><strong>Open degree obligations:</strong> analytical mechanics, solid-state and nuclear/particle foundations, thermal/statistical and quantum depth, advanced inference and physical apparatus/collaboration remain in the ${link('/programme/coverage/','coverage register')}. Introductory references in P101 or optional specialist study do not close these gaps.</p><p><strong>Construction disposition:</strong> parent/peer map approved; M101 block proposal is now available for review. This does not approve its blocks or units. Blueprint the complete M101 block structure before its units. Keep each subsequent module review separate. Full Stage 1 units and the stronger M100 lesson-production gate remain outstanding. Free tools/data and representative workloads require validation during detailed design.</p>`)+
section('sources','07 / EVIDENCE','References and the limits of comparison.',`<p>The allocations above are LibraUni design proposals informed by these references. They are not claims of identical curricula, institutional affiliation or recognised credits. Detailed assessment-level comparison remains to be completed module by module.</p><ol class="source-list">${stageMap.sources.map(([name,url,note])=>`<li>${link(url,name)}<p>${e(note)}</p></li>`).join('')}</ol>`);
const m101BlockBody=section('blocks','M101 / APPROVED BLOCKS','Direction, change, accumulation and judgement.',`<p>${e(m101Blocks.status)} · ${e(m101Blocks.date)}. The ${link('/programme/stage-1/map/#m101','module-level scope')} is approved; these four blocks and allocations are approved. The complete unit blueprint below is approved; lessons are not yet defined.</p>${table('Approved M101 study blocks',['Block','Hours','Python hours included'],m101Blocks.blocks.map(b=>[link('#'+b.id,b.id+' · '+b.title),String(b.hours),String(b.pythonHours)]))}<p><strong>54 + 72 + 78 + 36 = 240 study hours, including 30 Python hours.</strong> Orientation 6 + TMAs 18 + final assessment 18 + revision 12 + feedback 6 = 60 additional hours. Total: 300 hours / 30 internal credits. These are original planning allocations, not measured timings or copied OU weeks. Python and embedded checkpoints are already inside block hours.</p><p>Vectors come first to support P101 force resolution. Differentiation precedes accumulation; the final smaller block teaches integrated validation and transfer. Numerical checks begin in earlier blocks, so they can be assessed independently before the final synthesis. The unit proposal identifies handover points; P101 receiving units are now defined in its approved map; semester dates remain to be coordinated.</p>${m101Blocks.blocks.map(b=>`<article class="unit-card" id="${b.id}"><h3>${e(b.id+' · '+b.title)}</h3><p>${b.hours} study hours, including ${b.pythonHours} Python hours · Prior blocks: ${b.requires.length?e(b.requires.join(', ')):'Stage 1 entry readiness'} · Outcomes: ${e(b.outcomes.join(', '))}</p><dl>${[['Purpose',b.purpose],['Scope',b.scope],['Boundaries',b.boundary],['Python',b.python],['Expected evidence',b.evidence],['Forward handover',b.handover],['Assessment role',b.assessment]].map(([title,text])=>`<dt>${e(title)}</dt><dd>${e(text)}</dd>`).join('')}</dl></article>`).join('')}${table('Proposed assessment positions — no dates or live submissions',['Assessment','Position','Evidence scope','Budget'],m101Blocks.assessments.map(row=>row.map(e)))}<p><strong>Block approval recorded:</strong> the 54/72/78/36 allocation and 30 included Python hours are settled. The unit proposal below tests B01 density and staged computing handovers. Final examination duration, permitted resources and scan/submission arrangements remain separate decisions.</p><p>Under the ${link('/programme/construction-policy/','construction policy')}, block approval permits unit blueprinting. It does not release lessons or start a timetable. Deferred mathematics must receive explicit homes during M102 design.</p><ol class="source-list">${m101Blocks.sources.map(([title,url,note])=>`<li>${link(url,title)}<p>${e(note)}</p></li>`).join('')}</ol>`);
const m101UnitBody=section('units','M101 / APPROVED UNIT BLUEPRINT','Thirteen units. One connected mathematical foundation.',`<p>${e(m101Units.status)} · version ${e(m101Units.version)} · ${e(m101Units.date)}. Each allocation includes explanation, worked examples, abstract and contextual practice, Python and embedded feedback. These are planning estimates, not OU week allocations. No lessons or assessment questions are released.</p>${table('M101 approved units',['Unit','Block','Study hours','Python hours included'],m101Units.units.map(u=>[link('#'+u.id,u.id+' · '+u.title),link('#'+u.block,u.block),String(u.hours),String(u.pythonHours)]))}<p>Unit study totals 240 hours; the separate 60-hour orientation, TMA, final-assessment, revision and feedback envelope is unchanged. Formative iCMAs at U03, U07 and U11 sit inside those unit hours. TMA 01 follows U03, TMA 02 follows U07 and TMA 03 follows U11; each has six separately budgeted hours. U13 has a formative synthesis checkpoint, not a fourth TMA or EMA.</p><p><strong>Entry:</strong> algebra, functions, basic geometry and trigonometry are readiness requirements, with targeted retrieval included here. M100 remains optional. P101 owns initial degree Python teaching: scalar arithmetic, variables, lists, functions and iteration before corresponding M101 code; arrays and plotting before array/graph work. No new software installation is silently added to M101.</p>${m101Units.units.map(u=>`<article class="unit-card" id="${u.id}"><p class="eyebrow">${e(u.block+' / '+u.id)} · APPROVED UNIT BLUEPRINT</p><h3>${e(u.title)}</h3><p>${u.hours} study hours, including ${u.pythonHours} Python hours. Prior units: ${u.requires.length?u.requires.map(id=>link('#'+id,id)).join(', '):'Module entry readiness'}. Outcome mapping: ${e(u.outcomes.join(', '))}.</p><dl>${[['Purpose',u.purpose],['Scope and learning targets',u.scope],['Boundary',u.boundary],['Python and external prerequisites',u.python],['Evidence and assessment',u.evidence],['Forward handover',u.handover]].map(([title,text])=>`<dt>${e(title)}</dt><dd>${e(text)}</dd>`).join('')}</dl></article>`).join('')}`)+section('unit-review','RECURSIVE REVIEW / POLICY 1.0','Construction ready; teaching not released.',`<p>The gate for blueprinting block units is met: all M101 blocks are approved and every Stage 1 module has an approved outcome, boundary and workload map. The ${link('/programme/stage-1/map/','peer map')}, ${link('/programme/#blueprint-audit','wider blueprint audit')} and ${link('/programme/coverage/','coverage register')} supply the surrounding context. Unit approval was recorded on 26 September 2026.</p>${table('M101 handover and review register',['Interface','Required sequence / remaining decision'],[
['P101 mathematical use','U01 components, U02 projections/products, U05 derivatives and U08 accumulation must precede their corresponding P101 applications. P101 receiving units are proposed: U04 vectors, U07 derivatives, U11 integration. Calendar timing remains unassigned; see the P101 pair review.'],
['P101 computing supply','List/function foundations precede U02/U03 code; array/plot foundations precede graph and array activities. Reconcile both module sequences before releasing a timetable or dependent lessons.'],
['M102 boundary','Allocate further integration, improper integrals, series, complex numbers, eigenmethods and ODEs explicitly in M102; this M101 proposal does not claim their coverage.'],
['Assessment coverage','O3/O4/O6 in TMA 01; O1/O5/O6 in TMA 02; O2/O5/O6 in TMA 03 with declared cumulative items. U13 and the final written examination sample all outcomes; independent executed code is evidenced in TMAs. Detailed task/rubric coverage remains a release gate.'],
['Capacity','B01 is deliberately bounded to elementary coordinate geometry and small systems. Review its 54-hour density and U05/U09 fluency needs when lessons are budgeted; do not add topics silently.'],
['Source limits','MIT historical calculus/vector syllabi inform the subject boundaries. Private OU guide and sample unit organisation informed dependencies, worked-example/practice structure and feedback placement; no proprietary content is reproduced. Fuller Imperial module verification remains outstanding.'],
['Release decision','No lessons, dates, enrolments or mastery claims. Next, design P101 and reconcile the concurrent pair. The stronger Stage 1 and M100 blueprint gates still apply.']
].map(row=>row.map(e)))}<p>Review evidence is recorded in the public source document <a href="https://github.com/LibraUni/librauni.github.io/blob/main/docs/m101-unit-review.md">M101 unit design review</a>. Tests verify budget and reference consistency; they do not establish academic completeness or institutional equivalence.</p>`);

const p101BlockBody=section('blocks','P101 / APPROVED BLOCKS','From measurement to physical explanation.',`<p>${e(p101Blocks.status)} · ${e(p101Blocks.date)}. The ${link('/programme/stage-1/map/#p101','module-level scope')} is approved. These four blocks are approved; the complete unit blueprint below is approved. Lessons are not yet defined.</p>${table('Approved P101 blocks',['Block','Study hours','Python hours included'],p101Blocks.blocks.map(b=>[link('#'+b.id,b.id+' · '+b.title),String(b.hours),String(b.pythonHours)]))}<p><strong>60 + 72 + 54 + 54 = 240 study hours, including 48 Python hours.</strong> Add orientation 6, TMAs 18, EMA 18, revision 12 and feedback 6: 300 hours / 30 internal credits. Computing, measurement practice and embedded iCMAs are included, not extra work. These are LibraUni estimates; semester duration and weekly deadlines remain unset pending an evidenced OU presentation reference and pair reconciliation.</p><p>Python foundations are taught early within B01 for concurrent M101. Mechanics carries the main quantitative development; waves/light and elementary field/circuit/atomic models broaden it. We retain meaningful abstract problem solving alongside practical investigations.</p>${p101Blocks.blocks.map(b=>`<article class="unit-card" id="${b.id}"><h3>${e(b.id+' · '+b.title)}</h3><p>${b.hours} hours, including ${b.pythonHours} Python hours. Prior blocks: ${b.requires.length?e(b.requires.join(', ')):'Stage 1 entry readiness'}. Outcomes: ${e(b.outcomes.join(', '))}.</p><dl>${[['Purpose',b.purpose],['Scope',b.scope],['Boundaries and mathematical prerequisites',b.boundary],['Python',b.python],['Practical work and deliverable',b.practical],['Evidence and assessment',b.evidence],['Forward handover',b.handover]].map(([t,d])=>`<dt>${e(t)}</dt><dd>${e(d)}</dd>`).join('')}</dl></article>`).join('')}`)+section('review','P101 / COHERENCE REVIEW','A concurrent pair, not two disconnected modules.',`<p>The block-construction gate in ${link('/programme/construction-policy/','policy 1.0')} is met by the approved ${link('/programme/stage-1/map/','Stage 1 peer map')} and provisional wider degree progression. ${link('/programme/stage-1/lu-m101/#units','M101’s approved units')} specify the mathematical handovers. Construction disposition: unit proposal permitted following block approval. Release disposition: no teaching, timetable or enrolment.</p>${table('P101 interfaces and open decisions',['Requirement','Design response'],[
['Early Python','B01 teaches scalar/list/function foundations before M101 U02/U03 code and arrays/plots before graph work. Its internal sequence must be proved feasible during unit design; no additional M101 induction budget.'],
['Vectors and calculus','M101 U01/U02 precede resolved forces; U05 precedes derivative-based motion. Early mechanics uses algebra and graphs. Variable-force work/continuous impulse is held for B04 after U08/U09.'],
['Assessments','Three six-hour TMAs follow B01/B02/B03. B04 adds formative checks; the 18-hour EMA combines investigation and cross-outcome written checks, including O4. Rubrics and exact component hours are still to be designed.'],
['Practical depth','Each block specifies an investigation, deliverable and validation. Supplied data and simulations provide a free route; they do not prove apparatus or teamwork skills. Tool access/licensing and reproducibility need verification before release.'],
['Capacity and coverage','B02 and B04 are dense. Keep examples bounded and test unit-hour feasibility before approval. Rotation/angular momentum, relativity, formal electromagnetism, thermal/statistical depth and quantum/matter/nuclear foundations require later core homes.'],
['Next step','The complete unit map and logical pair check are approved. Proceed to M102; calendar timing and lesson production remain pending.']
].map(row=>row.map(e)))}<p>Detailed public record: <a href="https://github.com/LibraUni/librauni.github.io/blob/main/docs/p101-block-review.md">P101 block design review</a>. Source comparison is preliminary; institutional equivalence is not claimed.</p><ol class="source-list">${p101Blocks.sources.map(([title,url,note])=>`<li>${link(url,title)}<p>${e(note)}</p></li>`).join('')}</ol>`);

const p101UnitBody=section('units','P101 / APPROVED UNIT BLUEPRINT','Thirteen units linking models, measurements and code.',`<p>${e(p101Units.status)} · version ${e(p101Units.version)} · ${e(p101Units.date)}. Scope statements define learning targets; each unit includes explanations, examples, practice and its stated practical work. All Python hours are included. Entry requires the Stage 1 mathematics readiness, but no prior Python and no compulsory M100.</p>${table('P101 approved units',['Unit','Block','Study hours','Python included'],p101Units.units.map(u=>[link('#'+u.id,u.id+' · '+u.title),link('#'+u.block,u.block),String(u.hours),String(u.pythonHours)]))}${p101Units.units.map(u=>`<article class="unit-card" id="${u.id}"><p class="eyebrow">${e(u.block+' / '+u.id)} · APPROVED UNIT BLUEPRINT</p><h3>${e(u.title)}</h3><p>${u.hours} hours, including ${u.pythonHours} Python hours. Prior P101 units: ${u.requires.map(id=>link('#'+id,id)).join(', ')||'Module entry readiness'}. M101 prerequisites: ${u.mathRequires.map(id=>link('/programme/stage-1/lu-m101/#'+id,id)).join(', ')||'None beyond entry mathematics'}. Outcomes: ${e(u.outcomes.join(', '))}.</p><dl>${[['Learning targets and scope',u.scope],['Python',u.python],['Practical work and deliverable',u.practical],['Evidence',u.evidence],['Boundary',u.boundary],['Forward handover',u.handover]].map(([t,d])=>`<dt>${e(t)}</dt><dd>${e(d)}</dd>`).join('')}</dl></article>`).join('')}`)+section('assessments','P101 / ASSESSMENT MAP','Independent work and breadth of understanding.',`${table('Proposed P101 assessment positions',['Assessment','After','Separate hours','Outcome coverage'],p101Units.assessments.map(a=>[e(a.id),link('#'+a.after,a.after),String(a.hours),e(a.outcomes.join(', '))]))}<p>Formative iCMAs in U03, U07 and U10 and a U13 checkpoint are included in study hours. The three TMAs use independent reasoning and code with documentation allowed, generated solutions excluded. Task rubrics and permitted assistance must be explicit before release.</p>${table('EMA 18-hour component budget',['Component','Hours','Role'],p101Units.ema.map(([t,h,r])=>[e(t),String(h),e(r)]))}<p>Orientation 6 + study 240 + TMAs 18 + EMA 18 + revision 12 + feedback 6 = 300 hours. Guided practice in U12/U13 prepares the EMA; it is not the submitted EMA or duplicate assessment time. No final examination is added.</p>`)+section('pair-review','M101 + P101 / LOGICAL SEQUENCE','The handovers fit; dates still need planning.',`${table('Proposed concurrent-pair handovers',['Connection','Study-hour evidence'],p101Units.handovers.map(row=>row.map(e)))}<p>These cumulative figures count unit study only and assume comparable progress through both modules. They demonstrate a feasible logical ordering, not a timetable or a guarantee for every pace. Orientation, TMAs, revision, feedback and personal date changes must be included in the joint calendar. P101 U01 → M101 U02 is the tight handover: place the latter’s coding after the former’s readiness check. If readiness takes longer, adjust the pair visibly rather than assume completion.</p><p>Policy 1.0 unit-construction gate is met by the approved P101 blocks and Stage 1 peer map. Unit approval was recorded on 26 September 2026; teaching release remains blocked by the wider blueprint gates. Next: M102 blocks, with no automatic enrolment or academic attainment.</p><p><strong>Free practical route:</strong> local Python notebooks, NumPy arrays and Matplotlib graphs; small original synthetic examples are labelled as such. Documented measured datasets require provenance and reuse checks before release. NumPy’s <a href="https://numpy.org/about/">official project page</a> confirms free open-source access; <a href="https://matplotlib.org/stable/project/license.html">Matplotlib’s licence</a> permits royalty-free use under its terms (checked 26 September 2026). Exact environment, accessibility and activity execution still need testing. A local original circuit model avoids a required hosted service. PhET remains an optional candidate; its dynamically rendered licence details were not verified in this review.</p><p>Private OU organisational references were reviewed during M101 design; this proposal retains explicit dependencies, worked-example/practice allocation and embedded feedback without copying content. Physics scope references remain in the block review above; fuller Imperial syllabus verification and later core gaps remain open.</p><p>Public review record: <a href="https://github.com/LibraUni/librauni.github.io/blob/main/docs/p101-unit-review.md">P101 unit and pair review</a>.</p>`);

const m102BlockBody=section('blocks','M102 / APPROVED BLOCKS','Structures, change and probability.',`<p>${e(m102Blocks.status)} · ${e(m102Blocks.date)}. The ${link('/programme/stage-1/map/#m102','module scope')} is approved. These five blocks are approved. The complete unit blueprint below is approved; lessons are not yet defined.</p>${table('Approved M102 blocks',['Block','Study hours','Python hours included'],m102Blocks.blocks.map(b=>[link('#'+b.id,b.id+' · '+b.title),String(b.hours),String(b.pythonHours)]))}<p><strong>36 + 48 + 48 + 66 + 42 = 240 study hours, including 34 Python hours.</strong> Orientation 6 + TMAs 18 + final assessment 18 + revision 12 + feedback 6 = 300 total hours / 30 internal credits. Python, practice and formative checks are included. These are original estimates, not copied OU weeks. Orientation concerns this module’s workflow and readiness; it does not repeat Python installation.</p>${m102Blocks.blocks.map(b=>`<article class="unit-card" id="${b.id}"><h3>${e(b.id+' · '+b.title)}</h3><p>${b.hours} study hours, including ${b.pythonHours} Python hours. Prior blocks: ${b.requires.length?e(b.requires.join(', ')):'M101 and P101 readiness'}. Outcomes: ${e(b.outcomes.join(', '))}.</p><dl>${[['Purpose',b.purpose],['Scope',b.scope],['Boundaries',b.boundary],['Python',b.python],['Assessment evidence',b.evidence],['Forward handover',b.handover]].map(([t,d])=>`<dt>${e(t)}</dt><dd>${e(d)}</dd>`).join('')}</dl></article>`).join('')}${table('M102 assessment proposal',['Assessment','Position','Outcome scope','Budget'],m102Blocks.assessments.map(row=>row.map(e)))}`)+section('review','M102 / RECURSIVE REVIEW','Keep the scope honest and the progression explicit.',`<p>Policy 1.0 module-block gate is met: all Stage 1 module roles, outcomes, boundaries and budgets are mapped; later stage/core-specialist progression is explicit but provisional. ${link('/programme/stage-1/lu-m101/#units','M101')} and ${link('/programme/stage-1/lu-p101/#units','P101')} now have approved unit maps. Unit proposal construction is permitted following block approval; teaching release remains separate.</p><p><strong>Capacity risks:</strong> B02 must fit both deferred integration and series; B04 must balance analytical practice with numerical error reasoning. Their unit allocations must demonstrate feasibility before approval. Probability has its own 42-hour budget and an explicit final-examination evidence requirement; it cannot disappear into an optional activity. No fourth TMA or extra credits are added.</p><p>A101 remains viable from Semester 1 prerequisites. Its future unit review must identify any enrichment using M102 and schedule it after teaching; late ODE/eigenproblem/probability knowledge cannot become a hidden dependency. Stage 2 still needs deeper multivariable methods, transforms, inference and theoretical physics. Naming introductory topics here does not close those gaps.</p><p>The final examination will use handwritten/scanned mathematical reasoning and supplied-code interpretation; exact duration, permitted resources, scanning arrangements and marking remain to be designed within the 18-hour envelope. Independent executed-code evidence belongs to TMAs.</p><p><strong>Next:</strong> review the complete unit map below, then revise A101’s blocks and units. No enrolment, dates or lessons have been created. Public record: <a href="https://github.com/LibraUni/librauni.github.io/blob/main/docs/m102-block-review.md">M102 block review</a>.</p><ol class="source-list">${m102Blocks.sources.map(([t,url,n])=>`<li>${link(url,t)}<p>${e(n)}</p></li>`).join('')}</ol>`);

const m102UnitBody=section('units','M102 / APPROVED UNIT BLUEPRINT','Fourteen units, with explicit boundaries.',`<p>${e(m102Units.status)} · version ${e(m102Units.version)} · ${e(m102Units.date)}. Entry: approved M101 outcomes and P101 computing readiness. Each allocation includes explanation, examples, abstract and contextual practice, Python and formative checks. Prior-unit links include the planned study sequence as well as conceptual dependencies.</p>${table('Approved M102 units',['Unit','Block','Study hours','Python included'],m102Units.units.map(u=>[link('#'+u.id,u.id+' · '+u.title),link('#'+u.block,u.block),String(u.hours),String(u.pythonHours)]))}${m102Units.units.map(u=>`<article class="unit-card" id="${u.id}"><p class="eyebrow">${e(u.block+' / '+u.id)} · APPROVED UNIT BLUEPRINT</p><h3>${e(u.title)}</h3><p>${u.hours} study hours, including ${u.pythonHours} Python hours. Prior units: ${u.requires.map(id=>link('#'+id,id)).join(', ')||'Semester 1 readiness'}. Outcomes: ${e(u.outcomes.join(', '))}.</p><dl>${[['Learning targets and scope',u.scope],['Boundaries',u.boundary],['Python',u.python],['Evidence',u.evidence],['Forward handover',u.handover]].map(([t,d])=>`<dt>${e(t)}</dt><dd>${e(d)}</dd>`).join('')}</dl></article>`).join('')}`)+section('unit-review','M102 / UNIT REVIEW','Coverage, workload and the next handover.',`${table('M102 proposed assessment map',['Assessment','After','Separate hours','Outcome scope'],m102Units.assessments.map(a=>[e(a.id),link('#'+a.after,a.after),String(a.hours),e(a.outcomes.join(', '))]))}<p>Embedded iCMAs after U05, U08, U11 and U14 are included in study hours. Three TMAs assess independent work, with documentation allowed for code and generated solutions excluded. Probability has formative written checks and explicit final-examination coverage; no fourth TMA. The 18-hour final envelope includes preparation, handwriting/scan checks and submission, not an 18-hour sitting. Exact exam format and rubrics remain release decisions.</p><p>All units total 240 hours, including 34 Python hours, within the unchanged 300-hour module budget. B02: integration 18, improper integrals 12, series 18. B04: first-order equations 24, second-order equations 24, numerical evolution 18. B05: events/conditioning 14, discrete variables 14, continuous densities 14. These bounded allocations must be tested again when lessons are planned; no silent expansion.</p><p><strong>A101:</strong> required work retains Semester 1 prerequisites. U02 phase, U05 approximation, U08 eigenmethods, U11 numerical evolution and U14 probability are possible enrichment handovers only after demonstrated readiness. A101’s revised units must make each use explicit; no joint calendar is claimed yet.</p><p><strong>Construction policy 1.0:</strong> all M102 blocks and Stage 1 peer scopes are approved, so unit blueprinting is permitted. Unit approval was recorded on 26 September 2026. Lessons remain unreleased under the wider blueprint gates. Later core probability/inference, multivariable methods, transforms and physics depth remain visible in the ${link('/programme/coverage/','coverage register')}.</p><p>Local Python, NumPy and Matplotlib continue the established free workflow; use small original models and analytical benchmarks, with no new paid service. Specific library calls, environment versions and activity accessibility/execution require verification when teaching is authored. Private OU organisational references inspected earlier inform explicit dependencies and practice/feedback structure; no proprietary content is copied.</p><ol class="source-list">${m102Units.sources.map(([t,url,n])=>`<li>${link(url,t)}<p>${e(n)}</p></li>`).join('')}</ol><p>Public record: <a href="https://github.com/LibraUni/librauni.github.io/blob/main/docs/m102-unit-review.md">M102 complete unit review</a>. Next after review: A101 block and unit revision.</p>`);

const outputs=[
 ['/programme/stage-1/map/','Stage 1 module map',[link('/programme/','Physics'),link('/programme/#stage-1','Stage 1'),'<span aria-current="page">Module map</span>'],mapBody],
 ['/programme/construction-policy/','Curriculum construction policy',[link('/programme/','Physics'),'<span aria-current="page">Construction policy</span>'],policyBody],
 [bridge.path,bridge.title,[link('/programme/','Physics'),'<span aria-current="page">Optional bridge · M100</span>'],bridgeBody],
 ['/programme/stage-1/lu-a101/',a101.title,[link('/programme/','Physics'),link('/programme/#stage-1','Stage 1'),'<span aria-current="page">Semester 2 · A101</span>'],aBody],
 ['/programme/coverage/','Curriculum coverage',[link('/programme/','Physics'),'<span aria-current="page">Coverage register</span>'],coverageBody],
 ...stage1Modules.filter(mod=>mod.code!=='LU-A101').map(mod=>[mod.path,mod.title,[link('/programme/','Physics'),link('/programme/#stage-1','Stage 1'),`<span aria-current="page">Semester ${mod.semester} · ${mod.code}</span>`],intro(`STAGE 1 / SEMESTER ${mod.semester} / ${mod.code}`,mod.title,mod.purpose,['LU-M101','LU-P101','LU-M102'].includes(mod.code)?'30 internal credits · 300 notional hours · Blocks and units approved':'30 internal credits · 300 notional hours · Unit design pending')+section('place','01 / MODULE ROLE','A fixed place in the programme.',`<p>Study alongside ${moduleLinks(semesters.find(s=>s.number===mod.semester).codes.filter(c=>c!==mod.code))}. ${mod.semester===1?'Begin with the mathematical and Python readiness needed for degree study; use optional M100 preparation where necessary.':'Build on M101 and P101 from Semester 1.'}</p>${timing}<p>${link('/programme/stage-1/map/#'+mod.code.slice(3).toLowerCase(),'Approved module outcomes, responsibilities and handovers')} are available. ${mod.code==='LU-M101'?'The approved unit blueprint appears below; teaching materials remain to be designed.':mod.code==='LU-P101'?'The approved blocks and units appear below; teaching materials remain to be designed.':'The approved blocks and units appear below; teaching materials remain to be designed.'} No schedule or enrolment is open.</p>${mod.code==='LU-M101'?`<p>The former foundations preview has moved to ${link(bridge.path,'M100 · Mathematics & Python bridge')}. M101 now means Mathematics for physics I.</p>`:''}`)+(mod.code==='LU-M101'?m101BlockBody+m101UnitBody:mod.code==='LU-P101'?p101BlockBody+p101UnitBody:mod.code==='LU-M102'?m102BlockBody+m102UnitBody:'')]),
];
for(const [path,title,crumbs,body] of outputs){fs.mkdirSync(root+path.slice(1),{recursive:true});fs.writeFileSync(root+path.slice(1)+'index.html',shell(title,crumbs,body));}
